// Function to determine maximum element in an array 
def findMax(arr, n): 
    max = arr[0] 

    for i in range(1, n): 
        if arr[i] > max: 
            max = arr[i] 
    return max

## Write a function to find the most frequent element in an array.

### Response
def findMostFrequent(arr): 
    count_arr = {} 
    for i in range(len(arr)): 
        if arr[i] in count_arr: 
            count_arr[arr[i]] += 1
        else: 
            count_arr[arr[i]] = 1
    max_frequency = max(count_arr.values()) 
    for key,value in count_arr.items(): 
        if value == max_frequency: 
            return key

## Write a Python function that encrypts a message using the Caesar cipher.

### Response
def caesar_encrypt(message, key):
    encrypted_message = ""
    for char in message:
        if char.isalpha():
            num = ord(char)
            num += key
            if char.isupper():
                if num > ord('Z'):
                    num -= 26
                elif num < ord('A'):
                    num += 26
            elif char.islower():
                if num > ord('z'):
                    num -= 26
                elif num < ord('a'):
                    num += 26
            encrypted_message += chr(num)
        else:
            encrypted_message += char
    return encrypted_message
